import 'dart:convert';
import 'dart:io';

import 'package:pandapay_domain/pandapay_domain.dart';
import 'package:test/test.dart';

/// Plan §7 "Real cards" (WP7): every issuer-verified worked example
/// (db/fixtures/card_worked_examples, C6) runs through the Dart engine v2
/// against the card as the loader would publish it — the snapshots in
/// db/fixtures/catalogue_v2_cards (generated by
/// api/scripts/catalogue_v2/snapshot_examples.js).
///
/// The JS twin is api/test/card_worked_examples.test.js; both compare the
/// expected currency's amount, value_inr (when given), excluded, and cap
/// deltas summed per CardPipeline cap id. Snapshot freshness (input hashes)
/// is checked on the JS side.
///
/// Known failures (catalogue_v2_cards/_known_failures.json) must still fail
/// in this engine, so a fix is noticed. Examples with engine_checkable false
/// (C8 D14a) are reported as skipped with their reason.
const _examplesDir = '../../db/fixtures/card_worked_examples';
const _snapshotDir = '../../db/fixtures/catalogue_v2_cards';
const _engine = 'dart';

Map<String, dynamic> _readJson(String path) =>
    jsonDecode(File(path).readAsStringSync()) as Map<String, dynamic>;

TxnRail _rail(String? value) =>
    const {
      'upi_qr': TxnRail.upiQr,
      'swipe': TxnRail.swipe,
      'online': TxnRail.online,
      'contactless': TxnRail.contactless,
      'atm': TxnRail.atm,
      'emi': TxnRail.emi,
      'unknown': TxnRail.unknown,
    }[value] ??
    TxnRail.unknown;

/// Half-up to 2 dp, as integer paise (C8 D12e).
int _paise(num value) => (value * 100 + 1e-6).round();

/// The C3.1 context. Worked examples name the app category by slug; the
/// snapshot's category ids are `cat-<slug>`. Some examples write the MCC as a
/// number; the contract says a 4-digit string.
RecommendationContext _context(Map<String, dynamic> ctx) {
  final slug = ctx['category_slug'] as String?;
  final mcc = ctx['mcc'];
  return RecommendationContext(
    amount: Money.fromRupees((ctx['amount'] as num).toDouble()),
    categoryId:
        ctx['category_id'] as String? ?? (slug == null ? null : 'cat-$slug'),
    categorySlug: slug,
    mcc: mcc is num ? mcc.toInt().toString().padLeft(4, '0') : mcc as String?,
    merchantName: ctx['merchant_name'] as String?,
    vpa: ctx['merchant_vpa'] as String?,
    merchantSlug: ctx['merchant_slug'] as String?,
    platform: ctx['platform'] as String?,
    rail: _rail(ctx['rail'] as String?),
    now: ctx['occurred'] == null
        ? null
        : DateTime.parse(ctx['occurred'] as String),
  );
}

/// Runs one example; returns the mismatches (empty = pass).
List<String> _check(
  Map<String, dynamic> wireCard,
  CardProduct card,
  Map<String, dynamic> example,
  MerchantDirectory directory,
) {
  final caps = (wireCard['cap_rules'] as List).cast<Map<String, dynamic>>();
  final idsBySource = <String, List<String>>{};
  final sourceOfCap = <String, String>{};
  for (final cap in caps) {
    final source = cap['source_local_id'] as String;
    idsBySource.putIfAbsent(source, () => []).add(cap['id'] as String);
    sourceOfCap[cap['id'] as String] = source;
  }
  final before =
      ((example['state_before'] as Map?)?['caps_by_source_id'] as Map?) ??
      const {};
  final consumed = <String, double>{
    for (final e in before.entries)
      for (final id in idsBySource[e.key] ?? const <String>[])
        id: (e.value as num).toDouble(),
  };
  final result = RecommendationEngine.evaluateRewardV2(
    card,
    _context(example['ctx'] as Map<String, dynamic>),
    capConsumedBefore: consumed,
    directory: directory,
  );

  final expect_ = example['expect'] as Map<String, dynamic>;
  final problems = <String>[];
  if (result.excluded != (expect_['excluded'] as bool? ?? false)) {
    problems.add(
      'excluded ${result.excluded}, expected ${expect_['excluded']}',
    );
  }
  final isPoints = expect_['currency'] == 'points';
  final actual = isPoints ? result.points : result.cashbackInr;
  final expected = _paise(expect_['amount'] as num);
  final got = actual == null ? (expected == 0 ? 0 : null) : _paise(actual);
  if (got != expected) {
    problems.add(
      '${isPoints ? 'points' : 'cashback_inr'} $actual, expected ${expect_['amount']}',
    );
  }
  final value = expect_['value_inr'] as num?;
  if (value != null && _paise(result.valueInr) != _paise(value)) {
    problems.add('value_inr ${result.valueInr}, expected $value');
  }

  final gotDeltas = <String, int>{};
  for (final e in result.capDeltas.entries) {
    final source = sourceOfCap[e.key] ?? e.key;
    gotDeltas[source] = (gotDeltas[source] ?? 0) + _paise(e.value);
  }
  final wantDeltas = <String, int>{
    for (final e
        in ((expect_['cap_deltas_by_source_id'] as Map?) ?? const {}).entries)
      if ((e.value as num) != 0) e.key as String: _paise(e.value as num),
  };
  for (final source in {...gotDeltas.keys, ...wantDeltas.keys}) {
    if (gotDeltas[source] != wantDeltas[source]) {
      problems.add(
        'cap $source delta ${(gotDeltas[source] ?? 0) / 100}, '
        'expected ${(wantDeltas[source] ?? 0) / 100}',
      );
    }
  }
  return problems;
}

void main() {
  final directoryJson = _readJson('$_snapshotDir/_directory.json');
  final directory = MerchantDirectory.fromJson({
    'merchants': directoryJson['merchants'],
    'platforms': directoryJson['platforms'],
  });
  final knownFailures =
      (_readJson('$_snapshotDir/_known_failures.json')['failures'] as Map)
          .cast<String, dynamic>();
  final files =
      Directory(_examplesDir)
          .listSync()
          .whereType<File>()
          .where((f) => f.path.endsWith('.json'))
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));

  test('worked examples and snapshots are present', () {
    expect(files, isNotEmpty);
    for (final file in files) {
      final slug =
          (jsonDecode(file.readAsStringSync()) as Map)['source_slug'] as String;
      expect(
        File('$_snapshotDir/$slug.json').existsSync(),
        isTrue,
        reason: 'no snapshot for $slug',
      );
    }
  });

  for (final file in files) {
    final doc = jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
    final slug = doc['source_slug'] as String;
    final snapFile = File('$_snapshotDir/$slug.json');
    if (!snapFile.existsSync()) continue; // reported above
    final wireCard =
        (jsonDecode(snapFile.readAsStringSync()) as Map)['card']
            as Map<String, dynamic>;
    final card = CardProductJson.fromJson(wireCard);

    group(slug, () {
      for (final example
          in (doc['examples'] as List).cast<Map<String, dynamic>>()) {
        final key = '$slug#${example['id']}';
        final name = '$key ${example['title']}';
        if (example['engine_checkable'] == false) {
          test(
            name,
            () {},
            skip:
                'not engine-checkable: ${example['not_checkable_reason'] ?? 'no reason given'}',
          );
          continue;
        }
        final known = knownFailures[key] as Map<String, dynamic>?;
        if (known != null &&
            (known['engines'] as List).cast<String>().contains(_engine)) {
          test(
            '$name [known failure: ${known['category']} -> ${known['routed_to']}]',
            () {
              final problems = _check(wireCard, card, example, directory);
              expect(
                problems,
                isNotEmpty,
                reason:
                    '$key now passes: remove it from '
                    'db/fixtures/catalogue_v2_cards/_known_failures.json',
              );
            },
          );
          continue;
        }
        test(name, () {
          final problems = _check(wireCard, card, example, directory);
          expect(problems, isEmpty, reason: '$key: ${example['why']}');
        });
      }
    });
  }
}
